describe('ToolRegistry function-valued definitions', () => {
  it('validates each call against the schema the function returns for that call', async () => {
    const registry = new ToolRegistry();
    const calls: Array<Record<string, unknown>> = [];
    let requiredField = 'location';
    registry.register(
      () => ({
        name: 'dynamic_probe',
        description: 'Probe tool',
        inputSchema: {
          $id: 'dynamic_probe',
          type: 'object',
          properties: {[requiredField]: {type: 'string'}},
          required: [requiredField],
        },
      }),
      async input => {
        calls.push(input);
        return 'ok';
      }
    );

    const first = await registry.execute('dynamic_probe', {location: 'Berlin'});
    requiredField = 'city';
    const second = await registry.execute('dynamic_probe', {location: 'Berlin'});

    expect({first: first.result, second: second.result, executorCalls: calls.length}).toEqual({
      first: 'ok',
      second: expect.stringMatching(/city/),
      executorCalls: 1,
    });
  });
});
EOF
